1	using System.Security.Claims;
2	using Gatekeeper.Web.Data;
3	using Microsoft.AspNetCore.Components.Authorization;
4	using Microsoft.EntityFrameworkCore;
5	
6	namespace Gatekeeper.Web.Services;
7	
8	/// <summary>Writes audit entries, capturing the current console operator automatically.</summary>
9	public interface IAuditLogger
10	{
11	    Task LogAsync(string action, string entityType, string entityId, string summary, Guid? customerId = null);
12	}
13	
14	public class AuditLogger(
15	    IDbContextFactory<GatekeeperDbContext> dbFactory,
16	    AuthenticationStateProvider authState) : IAuditLogger
17	{
18	    public async Task LogAsync(string action, string entityType, string entityId, string summary, Guid? customerId = null)
19	    {
20	        var state = await authState.GetAuthenticationStateAsync();
21	        var user = state.User;
22	
23	        await using var db = await dbFactory.CreateDbContextAsync();
24	        db.AuditLog.Add(new AuditLogEntry
25	        {
26	            Action = action,
27	            EntityType = entityType,
28	            EntityId = entityId,
29	            Summary = summary,
30	            CustomerId = customerId,
31	            ActorUserId = user.FindFirstValue(ClaimTypes.NameIdentifier),
