1	@page "/grants"
2	@using Microsoft.EntityFrameworkCore
3	@attribute [Authorize]
4	@rendermode @(new InteractiveServerRenderMode(prerender: false))
5	@inject IDbContextFactory<GatekeeperDbContext> DbFactory
6	@inject IAuditLogger Audit
7	
8	<PageTitle>Gatekeeper · Grants</PageTitle>
9	
10	<h1>Grants</h1>
11	<p class="text-muted">An allow or deny of a permission on a resource, attached to either a user or a role.</p>
12	
13	<div class="card mb-4">
14	    <div class="card-header">Add grant</div>
15	    <div class="card-body">
16	        <EditForm Model="form" OnValidSubmit="AddAsync">
17	            <DataAnnotationsValidator />
18	            <div class="row g-2 align-items-end">
19	                <div class="col-md-3">
20	                    <label class="form-label">Customer</label>
21	                    <InputSelect class="form-select" @bind-Value="form.CustomerId" @bind-Value:after="OnCustomerChanged">
22	                        <option value="">— select —</option>
23	                        @foreach (var c in customers)
24	                        {
25	                            <option value="@c.Id">@c.Name</option>
26	                        }
27	                    </InputSelect>
28	                    <ValidationMessage For="() => form.CustomerId" />
29	                </div>
30	                <div class="col-md-2">
31	                    <label class="form-label">Effect</label>
32	                    <InputSelect class="form-select" @bind-Value="form.Effect">
33	                        @foreach (var e in Enum.GetValues<GrantEffect>())
34	                        {
35	                            <option value="@e">@e</option>
36	                        }
37	                    </InputSelect>
38	                </div>
39	                <div class="col-md-3">
40	                    <label class="form-label">Permission</label>
41	                    <InputText class="form-control" placeholder="e.g. documents.read" @bind-Value="form.Permission" />
42	                    <ValidationMessage For="() => form.Permission" />
43	                </div>
44	                <div class="col-md-2">
45	                    <label class="form-label">Resource</label>
46	                    <InputText class="form-control" placeholder="* or project:42" @bind-Value="form.Resource" />
47	                    <ValidationMessage For="() => form.Resource" />
48	                </div>
49	                <div class="col-md-2">
