echo "=== PUT /api/policy ==="
curl -sk -o /dev/null -w "HTTP %{http_code}\n" -X PUT $B/api/policy -H 'Content-Type: application/json' -d '{
  "roles": [
    { "name": "Editor", "parent": "Staff" },
    { "name": "Staff",  "parent": null }
  ],
  "assignments": [
    { "subject": "user-42", "role": "Editor" }
  ],
  "grants": [
    { "subject": "user-42", "action": "document:read",   "resource": "doc-7", "effect": "Allow" },
    { "subject": "Staff",   "action": "document:delete", "resource": "doc-9", "effect": "Deny"  }
  ]
}'

echo; echo "=== POST /api/decisions  (user-42 document:delete doc-7 -> expect Deny, default) ==="
curl -sk -X POST $B/api/decisions -H 'Content-Type: application/json' -d '{"subject":"user-42","action":"document:delete","resource":"doc-7"}'; echo

echo "=== POST /api/decisions  (user-42 document:read doc-7 -> expect Allow, direct user grant) ==="
curl -sk -X POST $B/api/decisions -H 'Content-Type: application/json' -d '{"subject":"user-42","action":"document:read","resource":"doc-7"}'; echo

echo "=== POST /api/decisions  (user-42 document:delete doc-9 -> expect Deny, inherited from Staff) ==="
curl -sk -X POST $B/api/decisions -H 'Content-Type: application/json' -d '{"subject":"user-42","action":"document:delete","resource":"doc-9"}'; echo

echo "=== POST /api/decisions  (unknown subject -> expect Deny, default) ==="
curl -sk -X POST $B/api/decisions -H 'Content-Type: application/json' -d '{"subject":"nobody","action":"document:read","resource":"doc-7"}'; echo

